                        new DocumentProperties().setEventCountingMetaInfo(metaInfo))){
            for (int i = 0; i < outDocument.getNumberOfPages() && i < cmpDocument.getNumberOfPages(); i++) {
                List<PdfLinkAnnotation> outLinks = getLinkAnnotations(i + 1, outDocument);
