        LineSegment lineSegment = new LineSegment(new Vector(120.3246f, 769.4974f, 1.0f),
                new Vector(151.22923f, 769.4974f, 1.0f));

        LineSegment segmentToCheck = new LineSegment(new Vector(110.3246f, 769.4974f, 1.0f),
