                grandpa1.addChild(child4);

                // Unused layer with used children
                PdfLayer parent2 = new PdfLayer("Parent2", fromDocument);
                PdfLayer child5 = new PdfLayer("Child5", fromDocument);
                parent2.addChild(child5);
