    @Test
    public void primitivesRead() throws IOException {
        String filename = DESTINATION_FOLDER + "primitivesRead.pdf";
        PdfDocument document = new PdfDocument(CompareTool.createTestPdfWriter(filename));
        document.addNewPage();
