        PdfAction action = PdfAction.createHide("test", false);
        aa.setOnPageOpened(action);

        Assert.assertEquals(action.getPdfObject().getAsString(PdfName.T), aa.getOnPageOpened().getPdfObject().getAsString(PdfName.T));
